#include <stdbool.h>
#include <stdio.h>

/* Toy device: what the bootloader does with the UART console. */
static bool fuse_debug_disabled = true;    /* burned at end of line */
static bool unlock_token_valid(void) { return false; } /* signed, per device */

static void start_root_shell(void) { puts("uart: root shell"); }
static void log_only(void)         { puts("uart: boot log, no input"); }

static void uart_console(void) {
#ifdef DEV_BUILD
    start_root_shell();                     /* engineering builds only */
#else
    if (!fuse_debug_disabled || unlock_token_valid())
        start_root_shell();                 /* authenticated service mode */
    else
        log_only();                         /* production default */
#endif
}

int main(void) { uart_console(); return 0; }

def rom_boot(image):
    fw, pub, sig = image[:-96], image[-96:-64], image[-64:]
    if hashlib.sha256(pub).digest() != OTP_FINGERPRINT:
        return "REFUSE: key not ours"
    try:
        Ed25519PublicKey.from_public_bytes(pub).verify(sig, fw)
    except InvalidSignature:
        return "REFUSE: bad signature"
    return "BOOT " + fw.decode()

# Toy model of a boot check, one "instruction" per list entry. A fault that
# skips exactly one instruction is tried at every position; we count how
# often a BAD image still boots. Our own simulator, not any real chip.
GOOD = 0x3CA5965A                       # unlikely constant, not 1

def naive(s):
    return [lambda: s.update(ok=s["verify"]()),
            lambda: s.update(halt=not s["ok"]),        # if (!ok) halt
            lambda: s.update(boot=not s["halt"])]

def hardened(s):
    return [lambda: s.update(r1=GOOD if s["verify"]() else 0),
            lambda: s.update(r2=GOOD if s["verify"]() else 0),
            lambda: s.update(halt=s["r1"] != GOOD),
            lambda: s.update(halt=s["halt"] or s["r2"] != GOOD),
            lambda: s.update(boot=(not s["halt"]) and s["r1"] == GOOD
                                  and s["r2"] == GOOD)]

def run(prog, skip):
    s = {"verify": lambda: False,          # the image is BAD
         "ok": True, "r1": 0, "r2": 0, "halt": False, "boot": False}
    steps = prog(s)
    for i, step in enumerate(steps):
        if i != skip:
            step()
    return s["boot"], len(steps)

for name, prog in [("naive", naive), ("hardened", hardened)]:
    n = run(prog, None)[1]
    wins = [i for i in range(n) if run(prog, i)[0]]
    print(f"{name:8}: {n} steps, single skips that boot a bad image: {wins}")

import os
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
from cryptography.exceptions import InvalidSignature

class SecureElement:
    """Toy model: the key is generated inside and has no export call."""
    def __init__(self):
        self.__key = Ed25519PrivateKey.generate()   # born on-chip
    def public_key(self):
        return self.__key.public_key()
    def sign(self, challenge):
        return self.__key.sign(challenge)

# Factory: each unit makes its own key; the cloud records only public keys
fleet = {f"cam-{i:04d}": SecureElement() for i in range(3)}
registry = {sn: se.public_key() for sn, se in fleet.items()}

def cloud_login(serial, device):
    challenge = os.urandom(32)                       # fresh every time
    sig = device.sign(challenge)
    try:
        registry[serial].verify(sig, challenge)
        return "accepted"
    except InvalidSignature:
        return "rejected"

print("cam-0001 as itself  :", cloud_login("cam-0001", fleet["cam-0001"]))
print("cam-0002 posing as 1:", cloud_login("cam-0001", fleet["cam-0002"]))
print("revoke cam-0001 only:", registry.pop("cam-0001") is not None,
      "| fleet still trusted:", sorted(registry))

# OTP bits can go from 0 to 1 but never back, so a "thermometer" counter
# can only rise: its value is the number of the highest set bit.
otp = [0] * 8                     # 8 fuse bits, all unburned

def otp_value():
    return max((i + 1 for i, b in enumerate(otp) if b), default=0)

def burn_up_to(v):                # raising the floor = burning more bits
    for i in range(v):
        otp[i] = 1

def try_boot(name, rollback_ver, signed_ok=True):
    if not signed_ok:
        return f"{name}: REFUSE (signature)"
    if rollback_ver < otp_value():
        return f"{name}: REFUSE (rollback {rollback_ver} < floor {otp_value()})"
    if rollback_ver > otp_value():
        burn_up_to(rollback_ver)  # booting a newer image revokes older ones
    return f"{name}: BOOT, fuses now {''.join(map(str, otp))}"

print(try_boot("fw 1.0 (rb 1)", 1))
print(try_boot("fw 1.1 (rb 1)", 1))
print(try_boot("fw 2.0 (rb 2, fixes CVE)", 2))
print(try_boot("fw 1.1 (rb 1, old, signed)", 1))

