#include <stdio.h>
#include <stdint.h>
#include <string.h>

/* Toy protocol: [len_hi][len_lo][payload...]; len = total bytes claimed. */
static int handle_vuln(const uint8_t *pkt, size_t rx_len) {
    uint8_t buf[16];
    size_t claimed = (pkt[0] << 8) | pkt[1];
    memcpy(buf, pkt + 2, claimed - 2);           /* trusts the header */
    return (int)(claimed - 2);
}

static int handle_fixed(const uint8_t *pkt, size_t rx_len) {
    uint8_t buf[16];
    if (rx_len < 2) return -1;
    size_t claimed = (pkt[0] << 8) | pkt[1];
    if (claimed < 2 || claimed > rx_len) return -1;    /* header vs wire */
    if (claimed - 2 > sizeof buf) return -1;           /* fits the buffer */
    memcpy(buf, pkt + 2, claimed - 2);
    return (int)(claimed - 2);
}

int main(int argc, char **argv) {
    uint8_t ok[]  = {0x00, 0x06, 'p', 'i', 'n', 'g'};
    uint8_t lie[] = {0x00, 0x40, 'p', 'i', 'n', 'g'};  /* claims 64, sends 6 */
    printf("fixed ok:  %d\n", handle_fixed(ok, sizeof ok));
    printf("fixed lie: %d\n", handle_fixed(lie, sizeof lie));
    printf("vuln ok:   %d\n", handle_vuln(ok, sizeof ok));
    if (argc > 1) printf("vuln lie:  %d\n", handle_vuln(lie, sizeof lie));
    return 0;
}

import json, sys

# Advisory ICSA-20-168-01: Treck TCP/IP fixed in 6.0.1.67 and later.
FIXED_IN = {"treck tcp/ip": (6, 0, 1, 67)}

def ver(s): return tuple(int(p) for p in s.split("."))

bom = json.load(open(sys.argv[1]))
top = bom["metadata"]["component"]
print("firmware:", top["name"], top["version"])
for c in bom["components"]:
    name, v = c["name"], c.get("version")
    fixed = FIXED_IN.get(name.lower())
    if v is None:
        print(f"  UNKNOWN   {name}: no version, ask the supplier")
    elif fixed and ver(v) < fixed:
        print(f"  AFFECTED  {name} {v} (fixed in {'.'.join(map(str, fixed))})")
    else:
        print(f"  ok        {name} {v}")

